import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/configuration.md","filePath":"getting-started/configuration.md","lastUpdated":1792561504000}`),a={name:`getting-started/configuration.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p><code>emgr</code> is configured entirely through environment variables, read by <a href="https://github.com/vaam-store/image-resizer/blob/main/src/modules/env/env.rs" target="_blank" rel="noreferrer"><code>src/modules/env/env.rs</code></a> via <a href="https://docs.rs/envconfig" target="_blank" rel="noreferrer"><code>envconfig</code></a>. That file is the source of truth this page is generated against - a CI check (<code>.github/workflows/ci.yml</code>&#39;s <code>docs-env-drift</code> job, <code>.github/scripts/check_env_docs.py</code>) fails the build if this table drifts from it in either direction.</p><div class="info custom-block"><p class="custom-block-title">This page previously documented variables that don&#39;t exist</p><p><em>CACHE_ENABLED</em>, <em>CACHE_TTL_SECONDS</em>, <em>S3_BUCKET</em>, <em>S3_REGION</em> and <em>LOCAL_STORAGE_PATH</em> were listed here before but were never read by the code (GH #47). There is no response-cache TTL setting today (see <a href="https://github.com/vaam-store/image-resizer/issues/40" target="_blank" rel="noreferrer">GH #40</a>); the real storage variables are <code>MINIO_BUCKET</code>, <code>MINIO_REGION</code> and <code>LOCAL_FS_STORAGE_PATH</code>, documented below.</p></div><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to “Server”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>HOST</code></td><td>Interface the HTTP server binds to.</td><td><code>0.0.0.0</code></td></tr><tr><td><code>PORT</code></td><td>HTTP server port.</td><td><code>3000</code></td></tr><tr><td><code>CDN_BASE_URL</code></td><td>Base URL used to build the <code>Location</code> header on a successful resize - see <a href="./../user-guide/api-reference">Redirect status code</a> (a <code>301</code>, not <code>302</code>).</td><td><code>http://localhost:9000/image-cache</code></td></tr></tbody></table><h2 id="storage-backend-selection" tabindex="-1">Storage backend selection <a class="header-anchor" href="#storage-backend-selection" aria-label="Permalink to “Storage backend selection”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>STORAGE_TYPE</code></td><td>Which backend to use. Accepted values: <code>LOCAL_FS</code> (aliases <code>LOCALFS</code>, <code>LOCAL</code>), <code>S3</code> (alias <code>MINIO</code>), <code>IN_MEMORY</code> (aliases <code>INMEMORY</code>, <code>MEMORY</code> - test/dev only; refuses to start in a release build). Only takes effect for whichever storage feature(s) the binary was compiled with.</td><td><em>unset</em></td></tr><tr><td><code>STORAGE_SUB_PATH</code></td><td>Prefix prepended to every generated cache key, for either backend.</td><td><code>&quot;&quot;</code> (empty)</td></tr></tbody></table><h3 id="local-filesystem-storage" tabindex="-1">Local filesystem storage <a class="header-anchor" href="#local-filesystem-storage" aria-label="Permalink to “Local filesystem storage”">​</a></h3><p>Requires the binary to be built with <code>--features local_fs</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>LOCAL_FS_STORAGE_PATH</code></td><td>Local path resized images are written to.</td><td><code>./data/images</code></td></tr></tbody></table><h3 id="minio-s3-storage" tabindex="-1">MinIO / S3 storage <a class="header-anchor" href="#minio-s3-storage" aria-label="Permalink to “MinIO / S3 storage”">​</a></h3><p>Requires the binary to be built with <code>--features s3</code>. MinIO and AWS S3 share the same client (MinIO is S3-compatible), so there is a single set of variables for both.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>MINIO_ENDPOINT_URL</code></td><td>S3-compatible endpoint URL.</td><td><code>http://localhost:9000</code></td></tr><tr><td><code>MINIO_ACCESS_KEY_ID</code></td><td>Access key.</td><td><code>minioadmin</code></td></tr><tr><td><code>MINIO_SECRET_ACCESS_KEY</code></td><td>Secret key.</td><td><code>minioadmin</code></td></tr><tr><td><code>MINIO_BUCKET</code></td><td>Bucket resized images are written to.</td><td><code>image-cache</code></td></tr><tr><td><code>MINIO_REGION</code></td><td>Bucket region.</td><td><code>us-east-1</code></td></tr></tbody></table><h2 id="signed-urls" tabindex="-1">Signed URLs <a class="header-anchor" href="#signed-urls" aria-label="Permalink to “Signed URLs”">​</a></h2><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/27" target="_blank" rel="noreferrer">GH #27</a>, alongside the imgproxy-compatible signed-path URL scheme itself (see the <a href="./../user-guide/api-reference">API reference</a>). Signing is the default, not opt-in: with neither a key/salt configured nor <code>ALLOW_UNSIGNED_REQUESTS=true</code> set, the process refuses to start rather than silently serving <code>403</code> to every request.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>SIGNING_KEY</code></td><td>Hex-encoded HMAC-SHA256 key used to verify signed URLs. Required unless <code>ALLOW_UNSIGNED_REQUESTS=true</code>. imgproxy equivalent: <em>IMGPROXY_KEY</em>.</td><td><em>unset</em></td></tr><tr><td><code>SIGNING_SALT</code></td><td>Hex-encoded salt mixed into every signed URL&#39;s HMAC input. Required unless <code>ALLOW_UNSIGNED_REQUESTS=true</code>. imgproxy equivalent: <em>IMGPROXY_SALT</em>.</td><td><em>unset</em></td></tr><tr><td><code>ALLOW_UNSIGNED_REQUESTS</code></td><td>Opt-in escape hatch for local development: when <code>true</code>, a request whose signature segment is the literal <code>unsigned</code> bypasses verification entirely. Does not weaken verification of a real signature - it only widens the <code>unsigned</code> escape path.</td><td><code>false</code></td></tr></tbody></table><h2 id="ssrf-source-fetch-guard" tabindex="-1">SSRF / source-fetch guard <a class="header-anchor" href="#ssrf-source-fetch-guard" aria-label="Permalink to “SSRF / source-fetch guard”">​</a></h2><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/21" target="_blank" rel="noreferrer">GH #21</a> to stop the <code>url</code> query parameter from being used to reach internal services. Mirrors imgproxy&#39;s equivalent settings, named in each row below.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>MAX_REDIRECTS</code></td><td>Maximum redirects the source fetch follows; every hop is re-validated (scheme, allowlist, resolved address). imgproxy: <em>IMGPROXY_MAX_REDIRECTS</em>.</td><td><code>5</code></td></tr><tr><td><code>ALLOWED_SOURCES</code></td><td>Comma-separated allowlist of source URL prefixes. Unset allows any <code>http(s)</code> URL, still subject to the private-range guard below. A host matching an entry here is also exempted from the private-IP-range block (RFC1918/CGNAT/IPv6 ULA) for that hop, so an explicitly-named internal origin (a Kubernetes Service ClusterIP, an internal MinIO, a private CDN shield) is reachable (<a href="https://github.com/vaam-store/image-resizer/issues/57" target="_blank" rel="noreferrer">GH #57</a>) - loopback and link-local are unaffected and keep their own flags below. Re-checked on every redirect hop. imgproxy: <em>IMGPROXY_ALLOWED_SOURCES</em>.</td><td><em>unset</em></td></tr><tr><td><code>ALLOW_LOOPBACK_SOURCE_ADDRESSES</code></td><td>Opt-in to allow fetching from loopback addresses (blocked by default).</td><td><code>false</code></td></tr><tr><td><code>ALLOW_LINK_LOCAL_SOURCE_ADDRESSES</code></td><td>Opt-in to allow fetching from link-local addresses (blocked by default).</td><td><code>false</code></td></tr></tbody></table><h2 id="resolution-and-output-limits" tabindex="-1">Resolution and output limits <a class="header-anchor" href="#resolution-and-output-limits" aria-label="Permalink to “Resolution and output limits”">​</a></h2><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/26" target="_blank" rel="noreferrer">GH #26</a>. See the <a href="./../user-guide/api-reference">API reference</a> for how these interact with the <code>width</code>/<code>height</code> query parameters.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>MAX_SRC_RESOLUTION_MP</code></td><td>Maximum decoded <em>source</em> resolution in megapixels, checked against header dimensions before a full decode. imgproxy default: <em>IMGPROXY_MAX_SRC_RESOLUTION</em> = 50.</td><td><code>50</code></td></tr><tr><td><code>MAX_OUTPUT_WIDTH</code></td><td>Maximum requested output width in pixels.</td><td><code>4096</code></td></tr><tr><td><code>MAX_OUTPUT_HEIGHT</code></td><td>Maximum requested output height in pixels.</td><td><code>4096</code></td></tr><tr><td><code>MAX_ANIMATION_FRAMES</code></td><td>Maximum number of frames read from an animated GIF/WebP source before the animated encode path (<a href="https://github.com/vaam-store/image-resizer/issues/49" target="_blank" rel="noreferrer">GH #49</a>) refuses the request. Enforced while iterating frames, not after decoding all of them, so it bounds work spent on attacker-supplied input rather than just rejecting after the fact - a many-tiny-frames animation can be individually well within <code>MAX_SRC_RESOLUTION_MP</code> per frame while still being a real memory/CPU amplification via frame count alone.</td><td><code>512</code></td></tr></tbody></table><h2 id="watermarking-presets-and-the-processing-option-allowlist" tabindex="-1">Watermarking, presets and the processing-option allowlist <a class="header-anchor" href="#watermarking-presets-and-the-processing-option-allowlist" aria-label="Permalink to “Watermarking, presets and the processing-option allowlist”">​</a></h2><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/52" target="_blank" rel="noreferrer">GH #52</a>. See the <a href="./../user-guide/api-reference">API reference</a> for the <code>wm:</code>/<code>wmu:</code>, <code>pr:</code> request-option syntax these variables back.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>WATERMARK_URL</code></td><td>Default watermark image URL, used when a request sets <code>wm:</code> without its own <code>wmu:{base64url}</code>. Fetched through the same SSRF guard (<code>ALLOWED_SOURCES</code>, private-range block, redirect re-validation) as any other source URL. A request&#39;s own <code>wmu:</code> always takes priority over this default. imgproxy: <em>IMGPROXY_WATERMARK_URL</em>.</td><td><em>unset</em></td></tr><tr><td><code>PRESETS</code></td><td>Preset definitions: comma-separated <code>{name}={options}</code> entries, <code>{options}</code> itself <code>/</code>-separated processing-option segments - e.g. <code>thumbnail=rs:fill:300:300/q:80,default=el:1</code>. A preset named <code>default</code> is special: it is prepended ahead of every request&#39;s own segments automatically, even when the request never names a preset at all. A preset&#39;s own definition cannot contain a <code>pr:</code> segment (presets don&#39;t recurse). imgproxy: <em>IMGPROXY_PRESETS</em>.</td><td><em>unset</em></td></tr><tr><td><code>ALLOWED_PROCESSING_OPTIONS</code></td><td>Comma-separated allowlist of processing-option short codes (e.g. <code>rs,q,pr</code>) permitted directly in a request URL. Unset/blank means unrestricted. Restricts what a request can do directly - it does <strong>not</strong> apply to options used <em>inside</em> a preset&#39;s own definition, which is what lets an operator hand out a restricted set of presets while forbidding the raw options they&#39;re built from. imgproxy: <em>IMGPROXY_ALLOWED_PROCESSING_OPTIONS</em>.</td><td><em>unset</em> (unrestricted)</td></tr></tbody></table><h2 id="jpeg-encoding" tabindex="-1">JPEG encoding <a class="header-anchor" href="#jpeg-encoding" aria-label="Permalink to “JPEG encoding”">​</a></h2><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/76" target="_blank" rel="noreferrer">GH #76</a>. JPEG output is encoded via <a href="https://docs.rs/jpeg-encoder" target="_blank" rel="noreferrer"><code>jpeg-encoder</code></a> (a pure-Rust encoder, replacing <code>mozjpeg</code>/libjpeg-turbo as of #134) rather than the <code>image</code> crate&#39;s own encoder, which has no progressive-mode switch and hardcodes 4:2:2 chroma subsampling. See the <a href="./../user-guide/api-reference">API reference</a> for the <code>jpgo:{progressive}:{no_subsample}</code> and <code>mb:{bytes}</code> request-option syntax these variables set the deployment-wide default for - a request&#39;s own <code>jpgo:</code> segment always overrides these when present.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>JPEG_PROGRESSIVE</code></td><td>Encode JPEG output progressively (multi-scan) instead of baseline sequential when a request doesn&#39;t set <code>jpgo:</code>&#39;s <code>progressive</code> slot itself. Progressive JPEGs render incrementally and are often, but not always, smaller - see this change&#39;s own benchmark report rather than assuming a size win on every image. imgproxy: <em>IMGPROXY_JPEG_PROGRESSIVE</em>.</td><td><code>false</code></td></tr><tr><td><code>JPEG_NO_SUBSAMPLING</code></td><td>Encode JPEG chroma at full resolution (4:4:4) instead of this crate&#39;s default 4:2:2 when a request doesn&#39;t set <code>jpgo:</code>&#39;s <code>no_subsample</code> slot itself. 4:4:4 preserves colour detail on saturated edges (screenshots, logos, text on colour) at the cost of a larger file. imgproxy: <em>IMGPROXY_JPEG_NO_SUBSAMPLING</em>.</td><td><code>false</code></td></tr></tbody></table><h2 id="performance-tuning" tabindex="-1">Performance tuning <a class="header-anchor" href="#performance-tuning" aria-label="Permalink to “Performance tuning”">​</a></h2><p><code>PERFORMANCE_PROFILE</code> selects a preset (see <a href="https://github.com/vaam-store/image-resizer/blob/main/src/config/performance.rs" target="_blank" rel="noreferrer"><code>src/config/performance.rs</code></a>); every other variable in this section, if set, overrides that preset&#39;s value for just that one field.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>PERFORMANCE_PROFILE</code></td><td>One of <code>high_throughput</code>, <code>low_latency</code>, <code>memory_efficient</code> (case-insensitive). Unset (or blank/whitespace-only) falls back to per-field defaults below rather than a named preset. <strong>An unrecognised, non-blank value (e.g. a typo like <code>hgh_throughput</code>) refuses to start the process at all</strong>, mirroring <code>SigningConfig</code>/<code>MetricsAuthConfig</code>&#39;s fail-closed convention, rather than silently falling back to per-field defaults with a different effective configuration than the operator asked for — issue #83.</td><td><em>unset</em></td></tr><tr><td><code>MAX_CONCURRENT_DOWNLOADS</code></td><td>Maximum concurrent source-image downloads.</td><td><code>20</code></td></tr><tr><td><code>MAX_CONCURRENT_PROCESSING</code></td><td>Maximum concurrent image-processing tasks.</td><td>Host core count</td></tr><tr><td><code>HTTP_TIMEOUT_SECS</code></td><td>Timeout for the source-image HTTP client.</td><td><code>30</code></td></tr><tr><td><code>MAX_IMAGE_SIZE_MB</code></td><td>Maximum accepted source image size.</td><td><code>50</code></td></tr><tr><td><code>CPU_THREAD_POOL_SIZE</code></td><td>CPU-bound thread pool size for decode/resize/encode.</td><td>Host core count</td></tr><tr><td><code>ENABLE_HTTP2</code></td><td>Enable HTTP/2 for the source-image HTTP client.</td><td><code>true</code> (<code>false</code> under the <code>memory_efficient</code> profile, which trades it away for lower per-connection memory)</td></tr><tr><td><code>CONNECTION_POOL_SIZE</code></td><td>Source-image HTTP client&#39;s per-host connection pool size.</td><td><code>50</code></td></tr><tr><td><code>KEEP_ALIVE_TIMEOUT_SECS</code></td><td>Source-image HTTP client&#39;s keep-alive timeout.</td><td><code>60</code></td></tr></tbody></table><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to “Observability”">​</a></h2><p>Requires the binary to be built with <code>--features otel</code>. See <a href="./../deployment/docker">Docker deployment</a> for how <code>compose.yaml</code> wires these to the bundled Jaeger instance.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>LOG_LEVEL</code></td><td>Log verbosity (<code>trace</code>, <code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>).</td><td><code>debug</code></td></tr><tr><td><code>OTLP_SPAN_ENDPOINT</code></td><td>OTLP gRPC endpoint for traces.</td><td><code>http://localhost:4317</code></td></tr><tr><td><code>OTLP_METRIC_ENDPOINT</code></td><td>OTLP HTTP endpoint for metrics.</td><td><code>http://localhost:4318/v1/metrics</code></td></tr><tr><td><code>OTLP_SERVICE_NAME</code></td><td>Service name reported in traces/metrics.</td><td><code>rust-app-example</code></td></tr></tbody></table><h3 id="metrics-and-health-authentication" tabindex="-1"><code>/metrics</code> and <code>/health</code> authentication <a class="header-anchor" href="#metrics-and-health-authentication" aria-label="Permalink to “/metrics and /health authentication”">​</a></h3><p>Added under <a href="https://github.com/vaam-store/image-resizer/issues/77" target="_blank" rel="noreferrer">GH #77</a>, a leftover from #27&#39;s stated scope. <code>/metrics</code> is a Prometheus endpoint - it exposes request rates, cache hit ratios, error counts and latency histograms, which is precise reconnaissance for an attacker probing for expensive requests. Mirroring <code>SIGNING_KEY</code>/<code>SIGNING_SALT</code> (see <a href="#signed-urls">Signed URLs</a> above), requiring a token is the default, not opt-in: with neither <code>METRICS_AUTH_TOKEN</code> configured nor <code>ALLOW_UNAUTHENTICATED_METRICS=true</code> set, the process refuses to start rather than silently serving traffic telemetry to anyone who asks. This only applies to builds with <code>--features otel</code> - a build without it never mounts <code>/metrics</code> at all, so there is nothing to protect and no startup check to satisfy.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>METRICS_AUTH_TOKEN</code></td><td>Bearer token <code>/metrics</code> requires via <code>Authorization: Bearer &lt;token&gt;</code>. Compared in constant time. Required unless <code>ALLOW_UNAUTHENTICATED_METRICS=true</code>. Configure the same value in your Prometheus scraper&#39;s <code>authorization</code> scrape config.</td><td><em>unset</em></td></tr><tr><td><code>ALLOW_UNAUTHENTICATED_METRICS</code></td><td>Opt-in escape hatch: when <code>true</code>, <code>/metrics</code> is served without requiring a token at all. Does not weaken verification of a real token - it only ever widens the unauthenticated-access escape path.</td><td><code>false</code></td></tr></tbody></table><p>A request with a missing or invalid token gets <code>401 Unauthorized</code> with a <code>WWW-Authenticate: Bearer</code> header, not <code>403</code> - unlike signed-URL rejection, there&#39;s a real credential the caller can supply on a retry.</p><p><code>/health</code> is left unauthenticated on purpose, not by oversight: it is the target of Kubernetes liveness/readiness/startup probes (<code>helm/serverless/templates/knative-service.yaml</code>), which hit it directly over HTTP and have no practical way to carry a bearer token. It also only ever returns the literal string <code>OK</code> - none of the traffic/cache/latency detail <code>/metrics</code> exposes - so the risk the two endpoints present isn&#39;t comparable. If <code>/health</code> ever needs restricting, do it at the network layer (an ingress rule or <code>NetworkPolicy</code> scoped to the cluster&#39;s own probe traffic), not with application-layer auth that would break the probes it exists to serve.</p><h2 id="example-env-file" tabindex="-1">Example <code>.env</code> file <a class="header-anchor" href="#example-env-file" aria-label="Permalink to “Example .env file”">​</a></h2><p>See <a href="https://github.com/vaam-store/image-resizer/blob/main/.env.example" target="_blank" rel="noreferrer"><code>.env.example</code></a> in the repository root for a copy-pasteable starting point covering every variable above. Copy it to <code>.env</code> (which is gitignored - never commit real credentials there).</p><div class="language-dotenv"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">STORAGE_TYPE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOCAL_FS</span></span>
<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">LOCAL_FS_STORAGE_PATH</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">./data/images</span></span>
<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">CDN_BASE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:3000/api/images/files</span></span></code></pre></div><h2 id="docker-environment-variables" tabindex="-1">Docker environment variables <a class="header-anchor" href="#docker-environment-variables" aria-label="Permalink to “Docker environment variables”">​</a></h2><p>When running with Docker, pass environment variables with <code>-e</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STORAGE_TYPE=LOCAL_FS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LOCAL_FS_STORAGE_PATH=/app/data/images</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CDN_BASE_URL=http://localhost:3000/api/images/files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/vaam-store/image-resizer:fs-latest</span></span></code></pre></div><h2 id="helm-chart-configuration" tabindex="-1">Helm chart configuration <a class="header-anchor" href="#helm-chart-configuration" aria-label="Permalink to “Helm chart configuration”">​</a></h2><p>When deploying with Helm, configure the service via <code>values.yaml</code>&#39;s <code>configMaps.config.data</code> block. See the <a href="./../deployment/helm-chart">Helm Chart</a> documentation for details.</p>`,47)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};